(function () {
  "use strict";

  const taxonomy = window.sofievkaTaxonomy;
  const attributeSchema = window.sofievkaAttributeSchema;
  const sourceMappings = window.sofievkaSourceMappings;
  const routing = window.sofievkaCatalogRouting;
  const products = Array.isArray(window.sofievkaNormalizedProducts) ? window.sofievkaNormalizedProducts : [];
  const brands = Array.isArray(window.sofievkaBrands) ? window.sofievkaBrands : [];
  if (!taxonomy || !attributeSchema || !sourceMappings || !routing) throw new Error("Central catalog modules are incomplete.");

  const catalogState = Object.freeze({
    id: "all",
    slug: "",
    name: "Усі товари",
    title: "Каталог обладнання",
    shortTitle: "Увесь каталог",
    description: "Інженерне обладнання для опалення, водопостачання, сантехніки та клімату.",
    menuDescription: "Усі товари та фільтри в одному каталозі",
    order: 0,
    status: "state",
    metaTitle: "Каталог інженерного обладнання | ТД «Софіївка»"
  });
  const sections = taxonomy.businessSections;
  const categories = taxonomy.productCategories;
  const sectionById = Object.freeze({ all: catalogState, ...Object.fromEntries(sections.map(section => [section.id, section])) });
  const categoryById = taxonomy.byId;
  const attributeDefinitions = attributeSchema.definitions;

  function sectionUrl(sectionId = "all") {
    return sectionId === "all" ? routing.rootPath : routing.getCategoryPath(sectionId);
  }

  function categoryUrl(categoryId) {
    return routing.getCategoryPath(categoryId);
  }

  function brandUrl(brandId) { return `/brands/${encodeURIComponent(brandId)}`; }
  function descendantIds(categoryId) { return new Set([categoryId, ...taxonomy.descendantsOf(categoryId).map(category => category.id)]); }
  function productsForSection(sectionId) { return sectionId === "all" ? [...products] : products.filter(product => product.sectionId === sectionId); }
  function productsForCategory(categoryId) {
    const ids = descendantIds(categoryId);
    return products.filter(product => ids.has(product.primaryCategoryId));
  }
  function availableCategories(sectionId) {
    return taxonomy.childrenOf(sectionId).filter(category => category.status === "active" && productsForCategory(category.id).length > 0);
  }
  const activeSections = Object.freeze(sections.filter(section => section.status === "active" && productsForSection(section.id).length > 0));
  const navigationSections = Object.freeze([catalogState, ...activeSections]);

  function resolveRoute(pathname = location.pathname, search = location.search, pageName = "catalog") {
    return routing.resolveLocation(pathname, search, pageName);
  }

  function valueLabel(definition, value) {
    if (attributeSchema.valueLabels[value]) return attributeSchema.valueLabels[value];
    if (definition?.type === "number") return `${new Intl.NumberFormat("uk-UA", { maximumFractionDigits: 4 }).format(Number(value))} ${definition.unit}`;
    return String(value);
  }

  const waterCategories = taxonomy.childrenOf("water-treatment");
  const waterGroups = [...new Set(waterCategories.map(category => category.legacyGroup))].map(groupId => Object.freeze({
    slug: groupId,
    name: waterCategories.find(category => category.legacyGroup === groupId)?.legacyGroupTitle || groupId,
    children: Object.freeze(waterCategories.filter(category => category.legacyGroup === groupId).map(category => Object.freeze({ slug: category.slug, name: category.title })))
  }));
  const waterCategoryBySlug = Object.freeze(Object.fromEntries(waterCategories.map(category => [category.slug, Object.freeze({
    slug: category.slug,
    name: category.title,
    groupSlug: category.legacyGroup,
    groupName: category.legacyGroupTitle
  })])));
  const waterProducts = Object.freeze(products.filter(product => product.sectionId === "water-supply"));
  const distribution = Object.freeze(Object.fromEntries(waterCategories.map(category => [category.id, productsForCategory(category.id).length])));
  window.sofievkaWaterCatalog = Object.freeze({
    taxonomy: Object.freeze(waterGroups),
    categoryBySlug: waterCategoryBySlug,
    supplierMappings: sourceMappings.supplierLabelMappings.ecosoft,
    products: waterProducts,
    report: Object.freeze({
      sourceCount: window.sofievkaNormalizationReport?.waterSourceCount || waterProducts.length,
      normalizedCount: waterProducts.length,
      uncategorized: Object.freeze(waterProducts.filter(product => !categoryById[product.primaryCategoryId]).map(product => product.id)),
      duplicateIds: window.sofievkaNormalizationReport?.duplicateInputIds || Object.freeze([]),
      ambiguous: Object.freeze([]),
      distribution
    })
  });
  window.sofievkaProducts = waterProducts;

  window.sofievkaCatalog = Object.freeze({
    catalogState,
    sections,
    activeSections,
    navigationSections,
    categories,
    taxonomy,
    sectionById,
    categoryById,
    attributeDefinitions,
    attributeSchema,
    sourceMappings,
    products,
    brands,
    slugify: window.sofievkaProductNormalizer.slugify,
    sectionUrl,
    categoryUrl,
    getCategoryPath: routing.getCategoryPath,
    getCategoryAncestors: routing.getCategoryAncestors,
    brandUrl,
    productsForSection,
    productsForCategory,
    availableCategories,
    resolveRoute,
    valueLabel
  });
})();

/* Source: catalog/pdp-engine.js */
(function () {
  "use strict";

  const catalog = window.sofievkaCatalog;
  if (!catalog) throw new Error("Catalog facade must load before the PDP engine.");

  const schema = catalog.attributeSchema || {};
  const definitions = catalog.attributeDefinitions || {};
  const products = catalog.products || [];
  const brands = catalog.brands || [];
  const groupDefinitions = Object.freeze([
    Object.freeze({ id: "main", title: "Основні параметри", keys: Object.freeze(["productType", "purpose", "type", "technology", "waterSource", "installation", "flowType", "scope", "pump", "mineralizer"]) }),
    Object.freeze({ id: "performance", title: "Робочі параметри", keys: Object.freeze(["capacityLh", "flowM3h", "headM", "kvs", "powerKw", "heatOutputKw", "pressureBar", "temperature", "filtrationMicron"]) }),
    Object.freeze({ id: "connection", title: "Підключення та сумісність", keys: Object.freeze(["diameter", "diameterMm", "connection", "mountingLengthMm", "outlets", "compatibility", "control", "voltage", "protectionClass", "material"]) }),
    Object.freeze({ id: "dimensions", title: "Габарити та формат", keys: Object.freeze(["widthMm", "heightMm", "depthMm", "volumeL", "weightKg", "format"]) })
  ]);

  const hasValue = value => value !== undefined && value !== null && value !== "";
  const genericSourceLabels = new Set(["категорія", "бренд", "стан", "наявність"]);
  const cleanSourceLabel = label => String(label || "").replace(/\s+/g, " ").trim();
  const splitSourceLabel = label => {
    const normalized = cleanSourceLabel(label);
    const grouped = normalized.match(/^(Вимоги до води[^:]*|Допустимі показники[^:]*|Основні властивості|Рекомендовані умови експлуатації|Технічні параметри|Технічні характеристики(?: матеріалу)?|Умови експлуатації|Характеристики (?:градієнтного картриджа|картриджа|кварцового піску|колби фільтра|матеріалу)[^:]*|Яку воду може очистити фільтр\?|Якість води[^:]*?)\*{0,3}:\s*(.+)$/i);
    return grouped ? { group: grouped[1].trim(), label: grouped[2].trim() } : { group: "Основні характеристики", label: normalized };
  };
  const canonicalSourceLabel = label => splitSourceLabel(label).label.toLocaleLowerCase("uk-UA").replace(/[.*]+$/g, "").replace(/\s+/g, " ").trim();

  function sourceSpecificationEntries(product) {
    const candidates = (Array.isArray(product.sourceAttributes) ? product.sourceAttributes : [])
      .filter(item => item?.label && hasValue(item.value) && !genericSourceLabels.has(cleanSourceLabel(item.label).toLocaleLowerCase("uk-UA")))
      .map((item, index) => {
        const parsed = splitSourceLabel(item.label);
        return { id: `source-${index}`, group: parsed.group, label: parsed.label, value: String(item.value).trim(), prefixed: parsed.group !== "Основні характеристики", canonicalLabel: canonicalSourceLabel(item.label) };
      });
    const groupedDuplicates = new Set(candidates.filter(item => item.prefixed).map(item => `${item.canonicalLabel}\u0000${item.value}`));
    const chosen = new Map();
    candidates.forEach(candidate => {
        if (!candidate.prefixed && groupedDuplicates.has(`${candidate.canonicalLabel}\u0000${candidate.value}`)) return;
        const key = `${candidate.group.toLocaleLowerCase("uk-UA")}\u0000${candidate.canonicalLabel}`;
        const current = chosen.get(key);
        if (!current || candidate.value.length > current.value.length) chosen.set(key, candidate);
      });
    return [...chosen.values()];
  }

  const keyPriorities = Object.freeze({
    "reverse-osmosis": [/номінальна продуктивність|продуктивність/, /накопичувальний бак/, /тиск на вході/, /кількість ступенів/, /монтаж/, /конверсія/, /температура води на вході|температура вхідної води/],
    "flow-filters": [/кількість ступенів/, /продуктивність/, /тиск/, /температура/, /підключення/],
    "mechanical-treatment": [/продуктивність робоча/, /робочий тиск/, /діаметр підключення|підключення установки/, /рейтинг фільтрації|тонкість фільтрації/, /ресурс/],
    "water-softening": [/продуктивність робоча/, /робочий тиск/, /об'єм фільтрувального матеріалу/, /витрата солі/, /діаметр підключення|підключення установки/],
    "complex-treatment": [/продуктивність робоча/, /робочий тиск/, /об'єм фільтрувального матеріалу/, /ресурс/, /діаметр підключення|підключення установки/],
    "chlorine-odor-removal": [/продуктивність робоча/, /робочий тиск/, /об'єм фільтрувального матеріалу/, /ресурс/, /діаметр підключення|підключення установки/],
    "mainline-filters-housings": [/рейтинг фільтрації|тонкість фільтрації/, /типорозмір/, /діаметр підключення|підключення/, /робочий тиск/, /температура води/],
    "drinking-system-cartridges": [/рекомендований інтервал заміни/, /тонкість фільтрації/, /кількість ступенів|кількість елементів/, /тип води/, /сумісність/],
    "mainline-cartridges": [/рейтинг фільтрації|тонкість фільтрації/, /тип картриджа/, /матеріал/, /типорозмір/, /ресурс/, /температура води/],
    "filter-media": [/маса|вага/, /об'єм/, /упаковка/, /робоча температура/, /робочий діапазон ph/, /застосування/]
  });
  const attributeEntry = (product, id) => {
    const value = product.normalizedAttributes?.[id];
    const definition = definitions[id];
    if (!definition || !hasValue(value)) return null;
    const sourceRecord = (product.catalogAttributes || []).find(item => item.id === id && hasValue(item.sourceValue));
    return Object.freeze({ id, label: definition.label, value: sourceRecord ? String(sourceRecord.sourceValue) : catalog.valueLabel(definition, value) });
  };

  function keySpecs(product, limit = 5) {
    if (product.source?.supplier === "ecosoft") {
      const entries = sourceSpecificationEntries(product);
      const priorities = keyPriorities[product.primaryCategoryId] || [];
      const selected = [];
      priorities.forEach(pattern => {
        const match = entries.find(item => pattern.test(item.label.toLocaleLowerCase("uk-UA")) && !selected.includes(item));
        if (match) selected.push(match);
      });
      entries.forEach(item => { if (selected.length < limit && !selected.includes(item)) selected.push(item); });
      return Object.freeze(selected.slice(0, limit).map((item, index) => Object.freeze({ id: `source-key-${index}`, label: item.label, value: item.value })));
    }
    const priority = schema.pdpPriorityByCategory?.[product.primaryCategoryId] || [];
    const fallback = schema.pdpFallbackPriority || Object.keys(definitions);
    return Object.freeze([...new Set([...priority, ...fallback])].flatMap(id => attributeEntry(product, id) || []).slice(0, limit));
  }

  function specificationGroups(product) {
    if (product.source?.supplier === "ecosoft") {
      const grouped = new Map();
      sourceSpecificationEntries(product).forEach(item => {
        if (!grouped.has(item.group)) grouped.set(item.group, []);
        grouped.get(item.group).push(Object.freeze({ id: item.id, label: item.label, value: item.value }));
      });
      return Object.freeze([...grouped.entries()].map(([title, items], index) => Object.freeze({ id: `source-group-${index}`, title, items: Object.freeze(items) })));
    }
    const normalizedIds = Object.keys(product.normalizedAttributes || {}).filter(id => definitions[id] && hasValue(product.normalizedAttributes[id]));
    const unmappedItems = (Array.isArray(product.unmappedAttributes) ? product.unmappedAttributes : [])
      .filter(item => item?.label && hasValue(item.value))
      .map(item => Object.freeze({ id: `source-${item.label}`, label: item.label, value: String(item.value) }));
    if (normalizedIds.length <= 5) {
      const items = normalizedIds.map(id => attributeEntry(product, id)).filter(Boolean);
      const groups = items.length ? [Object.freeze({ id: "technical", title: "Технічні дані", items: Object.freeze(items) })] : [];
      if (unmappedItems.length) groups.push(Object.freeze({ id: "complete", title: "Повні характеристики", items: Object.freeze(unmappedItems) }));
      return Object.freeze(groups);
    }
    const assigned = new Set();
    const groups = groupDefinitions.flatMap(group => {
      const ids = group.keys.filter(id => normalizedIds.includes(id));
      const items = ids.map(id => attributeEntry(product, id)).filter(Boolean);
      if (items.length < 2) return [];
      ids.forEach(id => assigned.add(id));
      return [Object.freeze({ id: group.id, title: group.title, items: Object.freeze(items) })];
    });
    const remaining = normalizedIds.filter(id => !assigned.has(id)).map(id => attributeEntry(product, id)).filter(Boolean);
    if (remaining.length) groups.push(Object.freeze({ id: "other", title: "Інші характеристики", items: Object.freeze(remaining) }));
    if (unmappedItems.length) groups.push(Object.freeze({ id: "complete", title: "Повні характеристики", items: Object.freeze(unmappedItems) }));
    return Object.freeze(groups);
  }

  function images(product) {
    const candidates = [product.image, ...(Array.isArray(product.images) ? product.images : []), ...(Array.isArray(product.gallery) ? product.gallery : [])]
      .map(item => typeof item === "string" ? item : item?.src)
      .filter(Boolean);
    return Object.freeze([...new Set(candidates)]);
  }

  function documents(product) {
    const sources = [
      ...(Array.isArray(product.documents) ? product.documents : []),
      ...(Array.isArray(product.instructions) ? product.instructions.map(item => typeof item === "string" ? { url: item, type: "Інструкція" } : { type: "Інструкція", ...item }) : []),
      ...(Array.isArray(product.downloads) ? product.downloads : [])
    ];
    const seen = new Set();
    return Object.freeze(sources.filter(item => {
      const url = typeof item === "string" ? item : item?.url;
      if (!url || !/^https?:\/\/|^\//.test(url) || seen.has(url)) return false;
      seen.add(url);
      return true;
    }).map(item => {
      const source = typeof item === "string" ? { url: item } : item;
      return Object.freeze({
        type: source.type || source.format || "Документ",
        title: source.title || source.name || "Документ виробника",
        url: source.url,
        size: source.size || source.fileSize || "",
        language: source.language || "",
        audience: source.audience || ""
      });
    }));
  }

  function referencedProducts(product, fields, limit = 4) {
    const references = fields.flatMap(field => Array.isArray(product[field]) ? product[field] : []);
    const result = [];
    const seen = new Set([product.id]);
    references.forEach(reference => {
      const key = typeof reference === "string" ? reference : reference?.productId || reference?.id || reference?.sku || reference?.slug;
      const match = products.find(item => item.id === key || item.sku === key || item.slug === key);
      if (!match || seen.has(match.id)) return;
      seen.add(match.id);
      result.push(match);
    });
    return Object.freeze(result.slice(0, limit));
  }

  function accessoryProducts(product, limit = 4) {
    return referencedProducts(product, ["accessoryIds", "accessories", "compatibleConsumables"], limit);
  }

  function compatibleProducts(product, limit = 4) {
    return referencedProducts(product, ["compatibleProductIds", "compatibleProducts"], limit);
  }

  function model(product) {
    const sourceModel = (product.unmappedAttributes || []).find(item => /^модель$/i.test(item.label) && hasValue(item.value))?.value;
    if (sourceModel) return String(sourceModel);
    if (product.model && product.model !== product.title) return String(product.model);
    return String(product.sku || product.id);
  }

  function purchase(product) {
    const status = product.inventory?.status || product.stockStatus || product.availability || "unknown";
    const amount = Number(product.pricing?.amount ?? product.price);
    const oldAmount = Number(product.pricing?.oldAmount ?? product.oldPrice ?? 0);
    return Object.freeze({
      status,
      statusLabel: product.availabilityLabel || (status === "in_stock" ? "В наявності" : status === "out_of_stock" ? "Немає в наявності" : "Наявність уточнюйте"),
      amount: Number.isFinite(amount) && amount > 0 ? amount : null,
      oldAmount: Number.isFinite(oldAmount) && oldAmount > amount ? oldAmount : null,
      purchasable: status === "in_stock" && Number.isFinite(amount) && amount > 0
    });
  }

  function relatedProducts(product, limit = 4) {
    const explicit = referencedProducts(product, ["similarProductIds", "similarProducts", "alternativeProductIds", "alternatives"], limit);
    if (explicit.length) return explicit;
    const sourceAttributes = product.normalizedAttributes || {};
    const titleStopTokens = new Set(["dlya", "with", "without"]);
    const titleFamily = item => {
      const brandTokens = new Set(catalog.slugify(item.brand || "").split("-").filter(Boolean));
      return catalog.slugify(item.shortTitle || item.title || "").split("-")
        .filter(token => token.length > 3 && !/^\d/.test(token) && !brandTokens.has(token) && !titleStopTokens.has(token))
        .slice(0, 3);
    };
    const sourceFamily = titleFamily(product);
    return Object.freeze(products.filter(item => item.id !== product.id && item.primaryCategoryId === product.primaryCategoryId).map(item => {
      const shared = Object.keys(sourceAttributes).filter(id => hasValue(sourceAttributes[id]) && sourceAttributes[id] === item.normalizedAttributes?.[id]).length;
      const familyOverlap = titleFamily(item).filter(token => sourceFamily.includes(token)).length;
      const sameSeries = Boolean(item.seriesId && item.seriesId === product.seriesId);
      const relevant = sameSeries || (shared >= 2 && familyOverlap >= 2);
      const score = (sameSeries ? 40 : 0) + (item.brandId === product.brandId ? 12 : 0) + shared * 5 + familyOverlap * 8;
      const priceDistance = Math.abs(Number(item.price || 0) - Number(product.price || 0));
      return { item, relevant, score, priceDistance };
    }).filter(entry => entry.relevant).sort((a, b) => b.score - a.score || a.priceDistance - b.priceDistance || a.item.id.localeCompare(b.item.id)).slice(0, limit).map(entry => entry.item));
  }

  function brand(product) {
    return brands.find(item => item.id === product.brandId) || null;
  }

  function installationRelevant(product) {
    return !new Set(["drinking-system-cartridges", "mainline-cartridges", "filter-media"]).has(product.primaryCategoryId);
  }

  window.sofievkaPdp = Object.freeze({ keySpecs, specificationGroups, images, documents, accessoryProducts, compatibleProducts, model, purchase, relatedProducts, brand, installationRelevant });
})();

/* Source: catalog/search-engine.js */
(function () {
  "use strict";

  const catalog = window.sofievkaCatalog;
  if (!catalog) throw new Error("Catalog search requires the centralized catalog facade.");

  const SEARCHABLE_ATTRIBUTE_IDS = Object.freeze([
    "diameter", "diameterMm", "connection", "powerKw", "headM", "flowM3h", "filtrationMicron",
    "compatibility", "kvs", "mountingLengthMm", "pressureBar", "heatOutputKw", "outlets", "voltage",
    "control", "protectionClass", "temperature", "capacityLh", "format"
  ]);

  const CATEGORY_ALIASES = Object.freeze({
    "circulation-pumps": ["циркуляційний насос", "циркуляційні насоси", "циркуляционный насос", "циркуляционные насосы"],
    "underfloor-heating": ["тепла підлога", "теплий пол", "теплый пол", "підігрів підлоги"],
    "distribution-hydraulics": ["гідравліка", "гидравлика", "колектор", "колектори", "коллектор", "насосна група"],
    automation: ["автоматика", "керування", "управління", "управление", "термостат", "контролер"],
    valves: ["арматура", "клапан", "клапани", "кран", "регулююча арматура"],
    "heating-components": ["комплектуючі", "комплектующие", "модульна система"],
    "water-treatment": ["водоочищення", "очищення води", "очистка воды", "фільтрація води"],
    "reverse-osmosis": ["осмос", "зворотний осмос", "зворотній осмос", "обратный осмос", "reverse osmosis"],
    "drinking-system-cartridges": ["картридж", "картриджі", "картриджи", "змінний елемент"],
    "mainline-cartridges": ["магістральний картридж", "магістральні картриджі", "картридж", "картриджі", "картриджи"],
    "mainline-filters-housings": ["магістральний фільтр", "корпус фільтра", "колба фільтра"],
    "filter-media": ["фільтрувальні матеріали", "фильтрующие материалы", "завантаження для фільтра", "засипка"],
    "complex-treatment": ["комплексне очищення", "комплексная очистка"],
    "water-softening": ["пом'якшення", "пом’якшення", "умягчение", "пом'якшувач"],
    "chlorine-odor-removal": ["видалення хлору", "хлор і запах", "удаление хлора"],
    "mechanical-treatment": ["механічне очищення", "механическая очистка"],
    "flow-filters": ["проточний фільтр", "проточні фільтри", "проточный фильтр"]
  });

  const WORD_GROUPS = Object.freeze([
    ["насос", "насоси", "насосы", "помпа", "помпи", "помпы"],
    ["картридж", "картриджі", "картриджи"],
    ["фільтр", "фільтри", "фильтр", "фильтры"],
    ["колектор", "колектори", "коллектор", "коллекторы"],
    ["клапан", "клапани", "клапаны"],
    ["керування", "управління", "управление"],
    ["циркуляційний", "циркуляційні", "циркуляционный", "циркуляционные"],
    ["зворотний", "зворотній", "обратный"],
    ["матеріал", "матеріали", "материал", "материалы"],
    ["фільтрувальний", "фільтрувальні", "фильтрующий", "фильтрующие"]
  ]);

  const STOP_WORDS = new Set(["і", "й", "та", "для", "з", "зі", "із", "в", "у", "на", "по", "и", "для"]);
  const SERIES_LABELS = catalog.attributeSchema.seriesLabels || {};

  function normalizeQuery(value) {
    return String(value ?? "")
      .normalize("NFKC")
      .replace(/[’‘`´]/g, "'")
      .replace(/\s+/g, " ")
      .trim()
      .toLocaleLowerCase("uk");
  }

  function tokenize(value) {
    return normalizeQuery(value).match(/[a-zа-яіїєґ0-9]+(?:[./-][a-zа-яіїєґ0-9]+)*/giu) || [];
  }

  const normalizedWordGroups = WORD_GROUPS.map(group => group.map(normalizeQuery));
  function variantsForToken(token) {
    const group = normalizedWordGroups.find(items => items.includes(token));
    return group || [token];
  }

  function unique(values) {
    return [...new Set(values.filter(Boolean))];
  }

  function phraseWithTokens(values) {
    const phrases = unique(values.map(normalizeQuery));
    return Object.freeze({ phrases: Object.freeze(phrases), tokens: Object.freeze(unique(phrases.flatMap(tokenize))) });
  }

  function technicalAttributeText(product) {
    const values = [];
    SEARCHABLE_ATTRIBUTE_IDS.forEach(id => {
      const value = product.normalizedAttributes?.[id];
      if (value === undefined || value === null || value === "") return;
      const definition = catalog.attributeDefinitions[id];
      const display = catalog.valueLabel(definition, value);
      values.push(id, definition?.label || "", display);
      if (/\d\s*["″]/.test(String(display))) values.push(`${String(display).replace(/["″]/g, "")} дюйм`, "inch");
    });
    return values;
  }

  function collectionText(product) {
    const collections = [
      ...(Array.isArray(product.collections) ? product.collections : []),
      ...(Array.isArray(product.tags) ? product.tags : [])
    ];
    return collections.flatMap(collection => {
      if (/sale|discount/i.test(collection)) return [collection, "sale", "розпродаж", "знижка"];
      return [collection];
    });
  }

  function identifierVariants(value) {
    const normalized = normalizeQuery(value).replace(/\s+/g, "");
    const variants = [normalized];
    // Supplier codes occasionally confuse the letter O and zero. Keep this controlled
    // equivalence below exact identifier matches instead of applying general fuzzy SKU search.
    if (/[oо](?=\d)|(?<=\d)[oо]/iu.test(normalized)) variants.push(normalized.replace(/[oо]/giu, "0"));
    if (/0(?=\d)|(?<=\d)0/u.test(normalized)) variants.push(normalized.replace(/0/g, "o"));
    return unique(variants);
  }

  const categoryIndex = Object.freeze(catalog.categories
    .filter(category => category.status === "active")
    .map(category => {
      const products = catalog.productsForCategory(category.id);
      const aliases = CATEGORY_ALIASES[category.id] || [];
      const parentNames = catalog.getCategoryAncestors(category.id).map(item => item.title || item.name);
      const text = phraseWithTokens([category.title, category.shortTitle, ...parentNames, ...aliases]);
      return Object.freeze({ type: "category", entity: category, count: products.length, href: catalog.getCategoryPath(category.id), aliases: Object.freeze(aliases), ...text });
    })
    .filter(item => item.count > 0));

  const productCountByBrand = catalog.products.reduce((counts, product) => {
    counts[product.brandId] = (counts[product.brandId] || 0) + 1;
    return counts;
  }, {});
  const brandIndex = Object.freeze(catalog.brands.map(brand => {
    const aliases = Array.isArray(brand.aliases) ? brand.aliases : [];
    const text = phraseWithTokens([brand.name, brand.slug, ...aliases]);
    return Object.freeze({ type: "brand", entity: brand, count: productCountByBrand[brand.slug] || 0, href: catalog.brandUrl(brand.slug), aliases: Object.freeze(aliases), ...text });
  }));

  const productIndex = Object.freeze(catalog.products.map(product => {
    const category = catalog.categoryById[product.primaryCategoryId];
    const categoryChain = category ? [...catalog.getCategoryAncestors(category.id), category] : [];
    const categoryAliases = categoryChain.flatMap(item => CATEGORY_ALIASES[item.id] || []);
    const seriesLabel = product.seriesId ? SERIES_LABELS[product.seriesId] || product.seriesId : "";
    const seriesName = product.seriesId ? `${product.brand} ${seriesLabel}` : "";
    const title = phraseWithTokens([product.title, product.shortTitle]);
    const model = phraseWithTokens([product.model]);
    const brand = phraseWithTokens([product.brand, product.brandId]);
    const series = phraseWithTokens([seriesName, seriesLabel, product.seriesId]);
    const categoryText = phraseWithTokens([...categoryChain.flatMap(item => [item.title, item.shortTitle]), ...categoryAliases]);
    const attributes = phraseWithTokens(technicalAttributeText(product));
    const collections = phraseWithTokens(collectionText(product));
    return Object.freeze({
      product,
      sku: normalizeQuery(product.sku).replace(/\s+/g, ""),
      skuVariants: Object.freeze(identifierVariants(product.sku)),
      title,
      model,
      brand,
      series,
      category: categoryText,
      attributes,
      collections
    });
  }));

  const seriesIndex = Object.freeze([...new Set(catalog.products.map(product => product.seriesId).filter(Boolean))].map(seriesId => {
    const products = catalog.products.filter(product => product.seriesId === seriesId);
    const brand = products[0]?.brand || "";
    const label = SERIES_LABELS[seriesId] || seriesId;
    const name = `${brand} ${label}`.trim();
    const text = phraseWithTokens([name, label, seriesId]);
    return Object.freeze({ type: "series", entity: Object.freeze({ id: seriesId, name, label, brand }), count: products.length, href: `/search?q=${encodeURIComponent(name)}`, aliases: Object.freeze([]), ...text });
  }));
  const fuzzyVocabulary = Object.freeze(unique([
    ...productIndex.flatMap(entry => [...entry.title.tokens, ...entry.brand.tokens, ...entry.category.tokens]),
    ...brandIndex.flatMap(entry => entry.tokens),
    ...categoryIndex.flatMap(entry => entry.tokens),
    ...seriesIndex.flatMap(entry => entry.tokens)
  ]));
  const fuzzyMatchCache = new Map();

  function levenshtein(first, second, maxDistance) {
    if (first === second) return 0;
    if (Math.abs(first.length - second.length) > maxDistance) return maxDistance + 1;
    let previous = Array.from({ length: second.length + 1 }, (_, index) => index);
    for (let i = 1; i <= first.length; i += 1) {
      const current = [i];
      let rowMinimum = i;
      for (let j = 1; j <= second.length; j += 1) {
        current[j] = Math.min(current[j - 1] + 1, previous[j] + 1, previous[j - 1] + (first[i - 1] === second[j - 1] ? 0 : 1));
        rowMinimum = Math.min(rowMinimum, current[j]);
      }
      if (rowMinimum > maxDistance) return maxDistance + 1;
      previous = current;
    }
    return previous[second.length];
  }

  function fuzzyTokenMatch(queryToken, candidateTokens) {
    if (!/^[a-zа-яіїєґ]+$/iu.test(queryToken) || queryToken.length < 4) return false;
    if (!fuzzyMatchCache.has(queryToken)) {
      const maxDistance = queryToken.length >= 8 ? 2 : 1;
      fuzzyMatchCache.set(queryToken, new Set(fuzzyVocabulary.filter(candidate => candidate.length >= 4 && levenshtein(queryToken, candidate, maxDistance) <= maxDistance)));
    }
    const matches = fuzzyMatchCache.get(queryToken);
    return candidateTokens.some(candidate => matches.has(candidate));
  }

  function phraseMatchScore(query, field, scores) {
    if (!query || !field.phrases.length) return 0;
    if (field.phrases.includes(query)) return scores.exact;
    if (field.phrases.some(value => value.startsWith(query))) return scores.prefix;
    if (field.phrases.some(value => value.includes(query))) return scores.contains;
    return 0;
  }

  function tokenMatchScore(token, entry) {
    const variants = variantsForToken(token);
    const fields = [
      [entry.title, 155, 95],
      [entry.model, 145, 90],
      [entry.brand, 135, 85],
      [entry.series, 130, 82],
      [entry.category, 125, 78],
      [entry.attributes, 72, 44],
      [entry.collections, 64, 38]
    ];
    if (variants.some(value => entry.skuVariants.includes(value))) return 900;
    if (/\d/u.test(token) && variants.some(value => entry.skuVariants.some(sku => sku.startsWith(value)))) return 620;
    for (const [field, exactScore, containsScore] of fields) {
      if (variants.some(value => field.tokens.includes(value))) return exactScore;
      if (variants.some(value => field.phrases.some(phrase => phrase.includes(value)))) return containsScore;
    }
    const fuzzyTokens = unique([...entry.title.tokens, ...entry.brand.tokens, ...entry.category.tokens]);
    return fuzzyTokenMatch(token, fuzzyTokens) ? 24 : 0;
  }

  function scoreProduct(entry, normalizedQuery, tokens) {
    const compact = normalizedQuery.replace(/\s+/g, "");
    if (entry.sku === compact) return 100000;
    if (entry.model.phrases.includes(normalizedQuery)) return 90000;
    if (entry.title.phrases.includes(normalizedQuery)) return 85000;
    const hasNumber = tokens.some(token => /\d/u.test(token));
    const hasUnit = tokens.some(token => ["мм", "м", "мкм", "квт", "вт", "бар", "л", "дюйм", "inch"].includes(token));
    const technicalPairs = tokens.flatMap((token, index) => /\d/u.test(token) && tokens[index + 1] ? [`${token} ${tokens[index + 1]}`] : []);
    if (hasNumber && hasUnit && ![entry.title, entry.model, entry.attributes].some(field => field.phrases.some(phrase => technicalPairs.some(pair => phrase.includes(pair))))) return 0;
    let score = 0;
    if (entry.sku.startsWith(compact)) score += 18000;
    else if (entry.skuVariants.includes(compact)) score += 12000;
    score += phraseMatchScore(normalizedQuery, entry.title, { exact: 0, prefix: 8000, contains: 4200 });
    score += phraseMatchScore(normalizedQuery, entry.model, { exact: 0, prefix: 7200, contains: 3600 });
    score += phraseMatchScore(normalizedQuery, entry.brand, { exact: 3200, prefix: 1900, contains: 1100 });
    score += phraseMatchScore(normalizedQuery, entry.series, { exact: 3000, prefix: 1700, contains: 1000 });
    score += phraseMatchScore(normalizedQuery, entry.category, { exact: 2800, prefix: 1500, contains: 900 });
    score += phraseMatchScore(normalizedQuery, entry.attributes, { exact: 0, prefix: 260, contains: 180 });
    score += phraseMatchScore(normalizedQuery, entry.collections, { exact: 500, prefix: 360, contains: 220 });

    let coverage = 0;
    let tokenScore = 0;
    tokens.forEach(token => {
      const matchScore = tokenMatchScore(token, entry);
      if (matchScore > 0) coverage += 1;
      tokenScore += matchScore;
      const variants = variantsForToken(token);
      if (variants.some(value => entry.category.tokens.includes(value))) tokenScore += 175;
      if (variants.some(value => entry.brand.tokens.includes(value))) tokenScore += 145;
      if (variants.some(value => entry.series.tokens.includes(value))) tokenScore += 135;
    });
    if (coverage !== tokens.length) return 0;
    score += tokenScore + (tokens.length > 1 ? coverage * 210 : 0);
    return score;
  }

  function scoreEntity(item, normalizedQuery, tokens) {
    const exact = item.phrases.includes(normalizedQuery);
    if (exact) return 10000;
    const prefix = item.phrases.some(value => value.startsWith(normalizedQuery));
    if (prefix) return 4800;
    const contains = item.phrases.some(value => value.includes(normalizedQuery));
    if (contains) return 2600;
    let coverage = 0;
    let score = 0;
    tokens.forEach(token => {
      const variants = variantsForToken(token);
      if (variants.some(value => item.tokens.includes(value))) { coverage += 1; score += 240; return; }
      if (fuzzyTokenMatch(token, item.tokens)) { coverage += 1; score += 45; }
    });
    return coverage === tokens.length ? score : 0;
  }

  function meaningfulTokens(query) {
    const all = tokenize(query);
    const filtered = all.filter(token => !STOP_WORDS.has(token));
    return filtered.length ? filtered : all;
  }

  function rankedEntities(items, normalizedQuery, tokens, limit, filter = () => true) {
    return items
      .filter(filter)
      .map(item => ({ ...item, score: scoreEntity(item, normalizedQuery, tokens) }))
      .filter(item => item.score > 0)
      .sort((first, second) => second.score - first.score || second.count - first.count || first.entity.name?.localeCompare(second.entity.name, "uk"))
      .slice(0, limit);
  }

  function search(query, options = {}) {
    const normalizedQuery = normalizeQuery(query);
    const tokens = meaningfulTokens(normalizedQuery);
    const limits = {
      products: Number.isFinite(options.productLimit) ? options.productLimit : Infinity,
      categories: Number.isFinite(options.categoryLimit) ? options.categoryLimit : Infinity,
      brands: Number.isFinite(options.brandLimit) ? options.brandLimit : Infinity,
      series: Number.isFinite(options.seriesLimit) ? options.seriesLimit : Infinity
    };
    if (!normalizedQuery || !tokens.length) return Object.freeze({ query: String(query ?? ""), normalizedQuery, totalProducts: 0, products: Object.freeze([]), productHits: Object.freeze([]), categories: Object.freeze([]), brands: Object.freeze([]), series: Object.freeze([]) });

    const allProductHits = productIndex
      .map(entry => ({ product: entry.product, score: scoreProduct(entry, normalizedQuery, tokens) }))
      .filter(hit => hit.score > 0)
      .sort((first, second) => second.score - first.score || first.product.title.localeCompare(second.product.title, "uk"));
    const exactBrandQuery = brandIndex.some(item => item.phrases.includes(normalizedQuery));
    const brands = rankedEntities(brandIndex, normalizedQuery, tokens, limits.brands, item => item.count > 0 || (exactBrandQuery && item.phrases.includes(normalizedQuery)));
    const categories = rankedEntities(categoryIndex, normalizedQuery, tokens, limits.categories);
    const series = rankedEntities(seriesIndex, normalizedQuery, tokens, limits.series);
    const productHits = allProductHits.slice(0, limits.products);
    return Object.freeze({
      query: String(query ?? ""),
      normalizedQuery,
      tokens: Object.freeze(tokens),
      totalProducts: allProductHits.length,
      products: Object.freeze(productHits.map(hit => hit.product)),
      productHits: Object.freeze(productHits),
      categories: Object.freeze(categories),
      brands: Object.freeze(brands),
      series: Object.freeze(series)
    });
  }

  const api = Object.freeze({
    search,
    normalizeQuery,
    tokenize,
    searchableAttributeIds: SEARCHABLE_ATTRIBUTE_IDS,
    aliases: CATEGORY_ALIASES,
    index: Object.freeze({ products: productIndex, brands: brandIndex, categories: categoryIndex, series: seriesIndex })
  });
  window.sofievkaCatalogSearch = api;
  window.catalogSearch = search;
})();
